SELECT monthly_fee_bucket, start_quarter, paused_count, plan_values FROM (SELECT CASE WHEN monthly_fee >= 255 THEN 'high' WHEN monthly_fee >= 64 THEN 'mid' ELSE 'low' END AS monthly_fee_bucket, QUARTER(start_date) AS start_quarter, SUM(CASE WHEN status = 'PAUSED' THEN 1 ELSE 0 END) AS paused_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(plan))) AS plan_values FROM subscriptions GROUP BY CASE WHEN monthly_fee >= 255 THEN 'high' WHEN monthly_fee >= 64 THEN 'mid' ELSE 'low' END, QUARTER(start_date)) AS s WHERE paused_count > 60
